window.docContents[87].resolve({"/Elementary-Functions/___4___26-Integrals/#chapter-4-section-26":{"contents":"Throughout §4.26 variables are real. The indefinite identities use the stated\nopen intervals to avoid singularities and principal-log branch changes. The\ndefinite identities include finite orthogonality integrals and improper\nintegrals interpreted as limits; inverse-trigonometric entries retain their\nreal endpoint restrictions.\n\n\n\n\n\n\n\n","context":"LMLF · DLMF with Lean\u0009Elementary Functions","header":"4.26. §4.26 Integrals","id":"/Elementary-Functions/___4___26-Integrals/#chapter-4-section-26"},"/Exponential___-Logarithmic___-Sine___-and-Cosine-Integrals/___6___14-Integrals/#chapter-6-section-14":{"contents":"Source: NIST Digital Library of Mathematical Functions, §6.14.\n\n\n\n","context":"LMLF · DLMF with Lean\u0009Exponential, Logarithmic, Sine, and Cosine Integrals","header":"6.14. §6.14 Integrals","id":"/Exponential___-Logarithmic___-Sine___-and-Cosine-Integrals/___6___14-Integrals/#chapter-6-section-14"}});